from PIL import Image
import colorsys
img = Image.open("barcode.png").convert("RGB")
w, h = img.size

def col_avg(x):
    rs=gs=bs=0
    for y in range(0, h, 4):
        r,g,b = img.getpixel((x,y))
        rs+=r; gs+=g; bs+=b
    n = len(range(0,h,4))
    return (rs//n, gs//n, bs//n)

cols = [col_avg(x) for x in range(w)]

def dist(a,b):
    return max(abs(a[i]-b[i]) for i in range(3))

stripes = []
start = 0
ref = list(cols[0])
for x in range(1, w):
    if dist(cols[x], ref) > 12:
        stripes.append((start, x-1, tuple(ref)))
        start = x
        ref = list(cols[x])
    else:
        for i in range(3):
            ref[i] = (ref[i]*3 + cols[x][i])//4
stripes.append((start, w-1, tuple(ref)))

print("num stripes:", len(stripes))
for s,e,rgb in stripes:
    r,g,b = [c/255 for c in rgb]
    hh,ss,vv = colorsys.rgb_to_hsv(r,g,b)
    wd = e-s+1
    print(f"x={s:4d}-{e:4d} w={wd:3d} rgb={rgb} hsv=({hh:5.1f},{ss:.2f},{vv:.2f}) #{rgb[0]:02x}{rgb[1]:02x}{rgb[2]:02x}")
EOF"}

