from PIL import Image
img = Image.open("barcode.png").convert("RGB")
w, h = img.size
cols = []
for x in range(w):
    rs=gs=bs=0
    for y in range(h):
        r,g,b = img.getpixel((x,y))
        rs+=r; gs+=g; bs+=b
    cols.append((rs/h, gs/h, bs/h))

edges = []
for x in range(1, w):
    d = sum(abs(cols[x][i]-cols[x-1][i]) for i in range(3))
    if d > 25:
        edges.append(x)
clusters = []
last = -10
for x in edges:
    if x - last > 2: clusters.append(x)
    last = x

best = None
for N in range(150, 400):
    W = w / N
    err = 0
    for e in clusters:
        k = round(e / W)
        err += (e - k*W)**2
    rms = (err/len(clusters))**0.5
    if best is None or rms < best[1]:
        best = (N, rms)
    if rms < 1.2:
        print(f"N={N} W={W:.3f} rms={rms:.3f}")
print("BEST:", best)
